DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[SalesOrderHeader]([SalesOrderID],[RevisionNumber],[OrderDate],[DueDate],[ShipDate],[Status],[OnlineOrderFlag],[SalesOrderNumber],[PurchaseOrderNumber],[AccountNumber],[CustomerID],[SalesPersonID],[TerritoryID],[BillToAddressID],[ShipToAddressID],[ShipMethodID],[CreditCardID],[CreditCardApprovalCode],[CurrencyRateID],[SubTotal],[TaxAmt],[Freight],[TotalDue],[Comment],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[SalesOrderID],S.[RevisionNumber],S.[OrderDate],S.[DueDate],S.[ShipDate],S.[Status],S.[OnlineOrderFlag],S.[SalesOrderNumber],S.[PurchaseOrderNumber],S.[AccountNumber],S.[CustomerID],S.[SalesPersonID],S.[TerritoryID],S.[BillToAddressID],S.[ShipToAddressID],S.[ShipMethodID],S.[CreditCardID],S.[CreditCardApprovalCode],S.[CurrencyRateID],S.[SubTotal],S.[TaxAmt],S.[Freight],S.[TotalDue],S.[Comment],S.[rowguid],S.[ModifiedDate],@B FROM ssis_flow.Delta_SalesOrderHeader S;
INSERT stg.[SalesOrderHeader]([SalesOrderID],[RevisionNumber],[OrderDate],[DueDate],[ShipDate],[Status],[OnlineOrderFlag],[SalesOrderNumber],[PurchaseOrderNumber],[AccountNumber],[CustomerID],[SalesPersonID],[TerritoryID],[BillToAddressID],[ShipToAddressID],[ShipMethodID],[CreditCardID],[CreditCardApprovalCode],[CurrencyRateID],[SubTotal],[TaxAmt],[Freight],[TotalDue],[Comment],[rowguid],[ModifiedDate],LoadBatchID) SELECT [SalesOrderID],[RevisionNumber],[OrderDate],[DueDate],[ShipDate],[Status],[OnlineOrderFlag],[SalesOrderNumber],[PurchaseOrderNumber],[AccountNumber],[CustomerID],[SalesPersonID],[TerritoryID],[BillToAddressID],[ShipToAddressID],[ShipMethodID],[CreditCardID],[CreditCardApprovalCode],[CurrencyRateID],[SubTotal],[TaxAmt],[Freight],[TotalDue],[Comment],[rowguid],[ModifiedDate],@B FROM etl_raw.[SalesOrderHeader];
INSERT etl_v2.SourceChange SELECT @B,N'Sales.SalesOrderHeader','I',@Next,(SELECT R.[SalesOrderID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[SalesOrderHeader] R;
END ELSE BEGIN
SELECT [SalesOrderID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_SalesOrderHeader FROM ssis_flow.Delta_SalesOrderHeader;
INSERT etl_v2.SourceChange SELECT @B,N'Sales.SalesOrderHeader',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[SalesOrderID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_SalesOrderHeader C LEFT JOIN etl_raw.[SalesOrderHeader] R ON R.[SalesOrderID]=C.[SalesOrderID];
DELETE R FROM etl_raw.[SalesOrderHeader] R JOIN #CT_SalesOrderHeader C ON R.[SalesOrderID]=C.[SalesOrderID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[RevisionNumber]=S.[RevisionNumber],R.[OrderDate]=S.[OrderDate],R.[DueDate]=S.[DueDate],R.[ShipDate]=S.[ShipDate],R.[Status]=S.[Status],R.[OnlineOrderFlag]=S.[OnlineOrderFlag],R.[SalesOrderNumber]=S.[SalesOrderNumber],R.[PurchaseOrderNumber]=S.[PurchaseOrderNumber],R.[AccountNumber]=S.[AccountNumber],R.[CustomerID]=S.[CustomerID],R.[SalesPersonID]=S.[SalesPersonID],R.[TerritoryID]=S.[TerritoryID],R.[BillToAddressID]=S.[BillToAddressID],R.[ShipToAddressID]=S.[ShipToAddressID],R.[ShipMethodID]=S.[ShipMethodID],R.[CreditCardID]=S.[CreditCardID],R.[CreditCardApprovalCode]=S.[CreditCardApprovalCode],R.[CurrencyRateID]=S.[CurrencyRateID],R.[SubTotal]=S.[SubTotal],R.[TaxAmt]=S.[TaxAmt],R.[Freight]=S.[Freight],R.[TotalDue]=S.[TotalDue],R.[Comment]=S.[Comment],R.[rowguid]=S.[rowguid],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[SalesOrderHeader] R JOIN #CT_SalesOrderHeader C ON R.[SalesOrderID]=C.[SalesOrderID] JOIN ssis_flow.Delta_SalesOrderHeader S ON S.[SalesOrderID]=C.[SalesOrderID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[SalesOrderHeader]([SalesOrderID],[RevisionNumber],[OrderDate],[DueDate],[ShipDate],[Status],[OnlineOrderFlag],[SalesOrderNumber],[PurchaseOrderNumber],[AccountNumber],[CustomerID],[SalesPersonID],[TerritoryID],[BillToAddressID],[ShipToAddressID],[ShipMethodID],[CreditCardID],[CreditCardApprovalCode],[CurrencyRateID],[SubTotal],[TaxAmt],[Freight],[TotalDue],[Comment],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[SalesOrderID],S.[RevisionNumber],S.[OrderDate],S.[DueDate],S.[ShipDate],S.[Status],S.[OnlineOrderFlag],S.[SalesOrderNumber],S.[PurchaseOrderNumber],S.[AccountNumber],S.[CustomerID],S.[SalesPersonID],S.[TerritoryID],S.[BillToAddressID],S.[ShipToAddressID],S.[ShipMethodID],S.[CreditCardID],S.[CreditCardApprovalCode],S.[CurrencyRateID],S.[SubTotal],S.[TaxAmt],S.[Freight],S.[TotalDue],S.[Comment],S.[rowguid],S.[ModifiedDate],@B FROM #CT_SalesOrderHeader C JOIN ssis_flow.Delta_SalesOrderHeader S ON S.[SalesOrderID]=C.[SalesOrderID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[SalesOrderHeader] R WHERE R.[SalesOrderID]=S.[SalesOrderID]);
INSERT stg.[SalesOrderHeader]([SalesOrderID],[RevisionNumber],[OrderDate],[DueDate],[ShipDate],[Status],[OnlineOrderFlag],[SalesOrderNumber],[PurchaseOrderNumber],[AccountNumber],[CustomerID],[SalesPersonID],[TerritoryID],[BillToAddressID],[ShipToAddressID],[ShipMethodID],[CreditCardID],[CreditCardApprovalCode],[CurrencyRateID],[SubTotal],[TaxAmt],[Freight],[TotalDue],[Comment],[rowguid],[ModifiedDate],LoadBatchID) SELECT R.[SalesOrderID],R.[RevisionNumber],R.[OrderDate],R.[DueDate],R.[ShipDate],R.[Status],R.[OnlineOrderFlag],R.[SalesOrderNumber],R.[PurchaseOrderNumber],R.[AccountNumber],R.[CustomerID],R.[SalesPersonID],R.[TerritoryID],R.[BillToAddressID],R.[ShipToAddressID],R.[ShipMethodID],R.[CreditCardID],R.[CreditCardApprovalCode],R.[CurrencyRateID],R.[SubTotal],R.[TaxAmt],R.[Freight],R.[TotalDue],R.[Comment],R.[rowguid],R.[ModifiedDate],@B FROM etl_raw.[SalesOrderHeader] R JOIN #CT_SalesOrderHeader C ON R.[SalesOrderID]=C.[SalesOrderID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;